%[text] # Build a nacelle from its CST parameters
%[text] Move a slider and the nacelle is rebuilt with `CST2Nacelle` (the second section runs again).
%[text] Kulfan (2008, Sec. X, option 1): the nacelle is a set of airfoil-type profiles in the meridional planes, distributed around the axis. The upper side of each airfoil is the outer cowl, the lower side the inner duct. The profiles are described exactly as wing sections, with the meridional angle `phi` (0 crown, 90 deg side, 180 deg keel) in place of the span.
%[text] Every coefficient is a Bernstein polynomial in `t = (1 - cos(phi))/2`; here they are linear (`ny = ny_plan = 1`), so each control value is the value on the crown line (`t = 0`) or on the keel line (`t = 1`), and the side profile is their average. Being a function of `cos(phi)`, the surface is smooth across the symmetry plane.
%[text] Default values: NACA 4412 profiles, keel line slightly larger and drooped.
%[text] ## Setup
clc; clear; close all
addpath(fullfile('..','src'))       % matlab_cst functions (run from the examples folder)

% plot settings
axFS = 13;
axFN = "Times New Roman";
lw   = 2;
axlw = 1.25;
set(0, 'defaultAxesTickLabelInterpreter','latex', ...
       'defaultTextInterpreter','latex', ...
       'DefaultLegendInterpreter','latex');
%%
%[text] ## CST parameters
% highlight radius [m]
Rle_crown = 1; %[control:slider:089a]{"position":[13,14]}
Rle_keel  = 1.1; %[control:slider:ea16]{"position":[13,16]}
% profile length [m]
c_crown = 3; %[control:slider:cfb6]{"position":[11,12]}
c_keel  = 2.8; %[control:slider:73fe]{"position":[11,14]}
% highlight x of the keel line [m] (crown at 0)
Xle_keel = -0.15; %[control:slider:269e]{"position":[12,17]}
% profile rotation [deg], positive = lip outward
twist_crown = 0; %[control:slider:12d2]{"position":[15,16]}
twist_keel  = -2; %[control:slider:3fa9]{"position":[15,17]}
% crown profile (outer cowl Au, inner duct Al, Al(1) = -Au(1))
AuC = zeros(4,1); AlC = zeros(4,1);
AuC(1) = 0.172; %[control:slider:1cc9]{"position":[10,15]}
AuC(2) = 0.343; %[control:slider:1fb2]{"position":[10,15]}
AuC(3) = 0.177; %[control:slider:93c3]{"position":[10,15]}
AuC(4) = 0.328; %[control:slider:9fff]{"position":[10,15]}
AlC(2) = 0.039; %[control:slider:1819]{"position":[10,15]}
AlC(3) = -0.106; %[control:slider:5a0d]{"position":[10,16]}
AlC(4) = 0.039; %[control:slider:0916]{"position":[10,15]}
% keel profile
AuK = zeros(4,1); AlK = zeros(4,1);
AuK(1) = 0.172; %[control:slider:17fe]{"position":[10,15]}
AuK(2) = 0.343; %[control:slider:febd]{"position":[10,15]}
AuK(3) = 0.177; %[control:slider:3786]{"position":[10,15]}
AuK(4) = 0.328; %[control:slider:e57e]{"position":[10,15]}
AlK(2) = 0.039; %[control:slider:08f9]{"position":[10,15]}
AlK(3) = -0.106; %[control:slider:e701]{"position":[10,16]}
AlK(4) = 0.039; %[control:slider:1b7e]{"position":[10,15]}

% BUILD ---------------------------------------------------------------------
AlC(1) = -AuC(1);  AlK(1) = -AuK(1);                    % same lip radius inside and outside
CST       = struct();
CST.Bu    = [AuC'; AuK'];                                % rows: crown (t = 0), keel (t = 1)
CST.Bl    = [AlC'; AlK'];
CST.Rle   = [Rle_crown; Rle_keel];                       % m
CST.c     = [c_crown; c_keel];                           % m
CST.Xle   = [0; Xle_keel];                               % m
CST.twist = deg2rad([twist_crown; twist_keel]);          % rad
Nac = CST2Nacelle(CST,phi=linspace(0,pi,25)',npsi=61);

% PLOT ----------------------------------------------------------------------
figure('Position',[100 100 1000 800]); %[output:1e483899]
tiledlayout(2,1,'TileSpacing','compact'); %[output:1e483899]
ax1 = nexttile; %[output:1e483899]
Nac.plot(ax1,profiles=false); %[output:1e483899]
view(ax1,[-125 20]); axis(ax1,'off'); %[output:1e483899]
ax2 = nexttile; hold on %[output:1e483899]
iSec = [1 13 25];                                        % crown, side, keel
cols = lines(3);
names = ["crown","side","keel"];
psi  = cosineSpacing(81);
for k = 1:3
    [xo,ro,xi,ri] = Nac.profile(iSec(k),psi);
    sgn = 1 - 2*(k == 3);                                % keel drawn below the axis
    plot(ax2,[flip(xo); xi(2:end)],sgn*[flip(ro); ri(2:end)],'-','Color',cols(k,:),'LineWidth',lw,'DisplayName',names(k)); %[output:1e483899]
end
yline(ax2,0,'k-.','HandleVisibility','off'); %[output:1e483899]
axis(ax2,'equal'); xlabel('$x$ [m]'); ylabel('$r$ [m] (keel below the axis)'); %[output:1e483899]
legend('Location','eastoutside'); styleAx(ax2,axFS,axFN,axlw); %[output:1e483899]
%%
%[text] ## Local functions
function styleAx(ax,axFS,axFN,axlw)
% axes style of the script skeleton
ax.FontName  = axFN;
ax.FontSize  = axFS;
ax.LineWidth = axlw;
ax.XMinorTick = "on"; ax.YMinorTick = "on";
ax.Layer = "top";
box(ax,'on'); grid(ax,'on');
ax.GridAlpha = 0.1;
end

